241	    fn save(&self, args: Self::SaveArgs) -> Result<Self::WriteResult, String> {
242	        let root = crate::ensured_notes_root(&self.app)?;
243	        let audio_bytes = decode_audio_base64(&args.audio_base64)?;
244	        if audio_bytes.is_empty() {
245	            return Err("Audio payload is empty.".to_string());
246	        }
247	
248	        let (target_folder_rel, target_folder_path) =
249	            resolve_recording_target_folder(&self.app, args.folder_path.as_deref())?;
250	        let extension = audio_extension_from_mime(args.mime_type.as_deref());
251	        let audio_path = recording_audio_file_path(&root, extension)?;
252	        fs::write(&audio_path, audio_bytes).map_err(|error| error.to_string())?;
253	
254	        let now = now_ms().unwrap_or(0);
255	        let note_id = generate_note_id();
256	        let note_file_name =
257	            recording_note_file_name(&target_folder_path, now, &note_id, args.file_name_format)?;
258	        let note_path = target_folder_path.join(&note_file_name);
259	        let mut meta = NoteFrontMatter::default();
260	        meta.id = Some(note_id);
261	        meta.created_ms = Some(now);
262	        meta.updated_ms = Some(now);
263	        meta.note_type = Some(RECORDING_FRONTMATTER_TYPE.to_string());
264	        meta.recording_audio_path = Some(strip_root(&root, &audio_path));
265	        meta.transcription_status = Some(RECORDING_STATUS_PENDING.to_string());
266	        meta.transcription_error = None;
267	        meta.transcription_updated_ms = Some(now);
268	        meta.transcription_id = None;
269	
270	        write_note_with_front_matter(&note_path, &meta, &recording_initial_body())?;
271	        if !crate::is_feed_folder_path(&root, &target_folder_path) {
272	            crate::update_order_append(&target_folder_path, &[note_file_name], false)?;
273	        }
274	
275	        Ok(RecordingWriteResult {
276	            folder_path: target_folder_rel,
277	            note_path: strip_root(&root, &note_path),
278	            audio_path: strip_root(&root, &audio_path),
279	        })
280	    }
