339	    fn list(&self) -> Result<Self::ListResult, String> {
340	        let root = crate::ensured_notes_root(&self.app)?;
341	        let queue = recording_queue_snapshot();
342	        let pending_set = queue
343	            .pending
344	            .iter()
345	            .map(String::as_str)
346	            .collect::<HashSet<_>>();
347	
348	        let mut recordings = collect_recording_notes(&root)?
349	            .into_iter()
350	            .map(|recording| {
351	                let folder_path = note_parent_folder_path(&recording.note_rel);
352	                let audio_exists = recording.audio_path.exists();
353	                let mut error = recording.error.clone();
354	                if !audio_exists {
355	                    error = Some("Audio file is missing.".to_string());
356	                }
357	                RecordingListItem {
358	                    note_path: recording.note_rel.clone(),
359	                    folder_path,
360	                    audio_path: if audio_exists {
361	                        Some(recording.audio_rel.clone())
362	                    } else {
363	                        None
364	                    },
365	                    status: recording.status.clone(),
366	                    error,
367	                    updated_ms: recording.updated_ms,
368	                    is_queued: pending_set.contains(recording.note_rel.as_str()),
369	                    is_processing: queue.current_recording.as_deref()
370	                        == Some(recording.note_rel.as_str()),
371	                }
372	            })
373	            .collect::<Vec<_>>();
374	
375	        recordings.sort_by(|a, b| b.updated_ms.unwrap_or(0).cmp(&a.updated_ms.unwrap_or(0)));
376	        Ok(RecordingsListResult { queue, recordings })
377	    }
