424	/// Access the global transcription queue mutex.
425	pub fn transcription_queue_state() -> &'static Mutex<TranscriptionQueueState> {
426	    TRANSCRIPTION_QUEUE.get_or_init(|| Mutex::new(TranscriptionQueueState::default()))
