429	/// Collect note paths that are currently queued or being transcribed.
430	pub fn active_transcription_note_paths() -> HashSet<String> {
431	    let queue = transcription_queue_state();
432	    let state = queue.lock().expect("transcription queue poisoned");
433	    let mut active = HashSet::with_capacity(state.pending.len() + 1);
434	    if let Some(current) = &state.current_recording {
435	        active.insert(current.clone());
436	    }
437	    active.extend(state.pending.iter().map(|job| job.note_rel.clone()));
438	    active
439	}
