441	/// Snapshot the current queue state for the frontend.
442	pub fn recording_queue_snapshot() -> RecordingQueueSnapshot {
443	    let queue = transcription_queue_state();
444	    let state = queue.lock().expect("transcription queue poisoned");
445	    let pending = state
446	        .pending
447	        .iter()
448	        .map(|job| job.note_rel.clone())
449	        .collect::<Vec<_>>();
450	    RecordingQueueSnapshot {
451	        running: state.running,
452	        current_recording: state.current_recording.clone(),
453	        in_flight: pending.len() + usize::from(state.running),
454	        pending,
455	    }
456	}
