504	/// Build the note body for a recording (transcript text or empty).
505	fn recording_note_body(status: &str, transcript: Option<&str>) -> String {
506	    if status != RECORDING_STATUS_COMPLETED {
507	        return String::new();
508	    }
509	    let value = transcript.unwrap_or_default().trim();
510	    if value.is_empty() {
511	        String::new()
512	    } else {
513	        format!("{}\n", value)
514	    }
515	}
