1	import { useCallback, useEffect, useMemo, useState } from "react";
2	import { formatRecordingStatus, formatUpdatedAt } from "@typenotes/shared/format";
3	import { useProfiles } from "@/features/profiles/hooks/profiles-context";
4	import { useRecordings } from "@/features/recording/hooks/recordings-context";
5	import { Button } from "@/shared/ui/button";
6	import type { RecordingListItem } from "@typenotes/shared/types";
7	import { WhisperEngineCard } from "./whisper-engine-card";
8	
9	/** Normalised, display-ready status for a recording (queued/processing take
10	 *  precedence over the persisted note status). */
11	type DisplayStatus =
12	  | "completed"
13	  | "processing"
14	  | "queued"
15	  | "pending"
16	  | "failed"
17	  | "unknown";
18	
19	function displayStatus(item: RecordingListItem): DisplayStatus {
20	  const raw = formatRecordingStatus(item).trim().toLowerCase();
21	  switch (raw) {
22	    case "completed":
23	    case "processing":
24	    case "queued":
25	    case "pending":
26	    case "failed":
27	      return raw;
28	    default:
29	      return "unknown";
30	  }
31	}
32	
33	const STATUS_META: Record<
34	  DisplayStatus,
35	  { label: string; badge: string; dot: string }
36	> = {
37	  completed: {
38	    label: "Completed",
39	    badge: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400",
40	    dot: "bg-emerald-500",
41	  },
42	  processing: {
43	    label: "Transcribing…",
44	    badge: "bg-sky-500/10 text-sky-600 dark:text-sky-400",
45	    dot: "bg-sky-500 animate-pulse",
46	  },
47	  queued: {
48	    label: "Queued",
49	    badge: "bg-amber-500/10 text-amber-600 dark:text-amber-400",
50	    dot: "bg-amber-500",
51	  },
52	  pending: {
53	    label: "Not transcribed",
54	    badge: "bg-muted text-muted-foreground",
55	    dot: "bg-muted-foreground/50",
56	  },
57	  failed: {
58	    label: "Failed",
59	    badge: "bg-destructive/10 text-destructive",
60	    dot: "bg-destructive",
61	  },
62	  unknown: {
63	    label: "Unknown",
64	    badge: "bg-muted text-muted-foreground",
65	    dot: "bg-muted-foreground/50",
66	  },
67	};
68	
69	function StatusBadge({ status }: { status: DisplayStatus }) {
70	  const meta = STATUS_META[status];
71	  return (
72	    <span
73	      className={`inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium ${meta.badge}`}
74	    >
75	      <span className={`h-1.5 w-1.5 rounded-full ${meta.dot}`} />
76	      {meta.label}
77	    </span>
78	  );
79	}
80	
81	function recordingTitle(notePath: string): string {
82	  const file = notePath.split("/").pop() ?? notePath;
83	  return file.replace(/\.md$/i, "");
84	}
85	
86	export function SettingsTranscriptionSection() {
87	  const { syncSettings, updateSyncSettings } = useProfiles();
88	  const {
89	    recordingsQueue,
90	    recordingsList,
91	    recordingsBusy,
92	    recordingsError,
93	    recordingStatusMessage,
94	    transcriptionQueueBusy,
95	    refreshRecordings,
96	    queueRecordingTranscriptions,
97	    retriggerTranscription,
98	    playRecording,
99	    activeAudioPath,
100	    activeAudioSrc,
101	  } = useRecordings();
102	
103	  const [busyPaths, setBusyPaths] = useState<Set<string>>(new Set());
104	
105	  // Navigate to the note itself. AppShell listens for this and leaves Settings.
106	  const openNote = useCallback((notePath: string) => {
107	    window.dispatchEvent(
108	      new CustomEvent("open-note", { detail: { notePath } })
109	    );
110	  }, []);
111	
112	  const setPathBusy = useCallback((path: string, busy: boolean) => {
113	    setBusyPaths((prev) => {
114	      const next = new Set(prev);
115	      if (busy) next.add(path);
116	      else next.delete(path);
117	      return next;
118	    });
119	  }, []);
120	
121	  useEffect(() => {
122	    void refreshRecordings();
123	  }, [refreshRecordings]);
124	
125	  // Live polling while any job is queued or processing.
126	  const hasActiveWork =
127	    (recordingsQueue?.in_flight ?? 0) > 0 ||
128	    recordingsList.some((item) => item.is_queued || item.is_processing);
129	
130	  useEffect(() => {
131	    if (!hasActiveWork) return;
132	    const id = window.setInterval(() => {
133	      void refreshRecordings();
134	    }, 2500);
135	    return () => window.clearInterval(id);
136	  }, [hasActiveWork, refreshRecordings]);
137	
138	  const counts = useMemo(() => {
139	    const base: Record<DisplayStatus, number> = {
140	      completed: 0,
141	      processing: 0,
142	      queued: 0,
143	      pending: 0,
144	      failed: 0,
145	      unknown: 0,
146	    };
147	    for (const item of recordingsList) base[displayStatus(item)] += 1;
148	    return base;
149	  }, [recordingsList]);
150	
151	  const failedItems = useMemo(
152	    () => recordingsList.filter((item) => displayStatus(item) === "failed"),
